files.agent-pane/theme.css:
/* Preserve native search, scrolling and viewport bounds. */
.acpmux-menu.acpmux-location-menu.acpmux-folder-popover {
  --ui-popup-radius: 14px;
  --ui-row-height: calc(28px * var(--cmux-interface-scale, 1));
  --ui-row-radius: 8px;
  --cmux-menu-highlight-radius: 8px;
}

files.customize/cmux-app.json:
{
  "$schema": "https://cmux.dev/schemas/cmux-app/2.json",
  "manifestVersion": 2,
  "id": "local/customize",
  "name": {
    "en": "Codex project picker"
  },
  "version": "1.0.0",
  "description": "Expose the active composer's project action beside the draft.",
  "engines": {
    "cmux": "^2.0"
  },
  "implements": {
    "cmux.composer.toolbar/1": {
      "options": {
        "buttons": [
          {
            "action": "composer.chooseProject",
            "label": "Work in a project"
          }
        ]
      }
    }
  }
}
